export const t=k=>copy[k]?.[{zh:0,'zh-Hant':1,en:2}[preferences.lang]??2]||k;
let api,guide,page=0,tour,step=0,highlight;
const node=(tag,text,cls)=>{const e=document.createElement(tag);if(text)e.textContent=text;if(cls)e.className=cls;return e};
const button=(text,fn)=>{const e=node('button',text);e.type='button';e.onclick=fn;return e};
function persist(){try{localStorage.setItem(KEY,JSON.stringify(preferences))}catch{}}
function apply(){document.documentElement.lang=preferences.lang==='zh'?'zh-CN':preferences.lang;document.body.dataset.controls=preferences.side;document.body.classList.toggle('reduce-motion',preferences.motion);document.dispatchEvent(new Event('portfolio-preferences'));document.querySelectorAll('iframe').forEach(f=>f.contentWindow?.postMessage({type:'portfolio-preferences',...preferences},location.origin));translate();}
function change(key,value){preferences[key]=value;persist();apply();}
function translate(){const map={'ABOUT ME':t('about'),'About Me':t('about'),'Project Content':t('projects'),'Exhibition&Paper':t('research'),'Exhibition&Papers':t('research'),'View Full Project ↗':t('full'),'Control Center':preferences.lang==='en'?'Control Center':'設定 / 设置'};document.querySelectorAll('[data-action="about"],[data-action="projects"],[data-action="research"],.full-project-button').forEach(e=>{if(e.children.length)return;if(!e.dataset.originalLabel)e.dataset.originalLabel=e.textContent;const text=map[e.dataset.originalLabel];if(text&&e.textContent!==text)e.textContent=text;});document.querySelectorAll('.guide-entry').forEach(e=>e.textContent='? '+t('guide'));}
export function preferenceControls(host){const box=node('div',null,'guide-preferences');function render(){box.replaceChildren();const lang=node('label',t('language'));const select=node('select');for(const [v,label]of [['zh','简体中文'],['zh-Hant','繁體中文'],['en','English']]){const o=node('option',label);o.value=v;select.append(o)}select.value=preferences.lang;select.onchange=()=>{change('lang',select.value);render();if(guide?.open)renderGuide()};lang.append(select);box.append(lang);const side=node('label',t('position'));const choices=node('div',null,'guide-choices');for(const value of ['left','right']){const b=button((value==='left'?'🔴 🟡 🟢  ──':'──  🔴 🟡 🟢')+'  '+t(value),()=>{change('side',value);render()});b.setAttribute('aria-pressed',preferences.side===value);choices.append(b)}side.append(choices);box.append(side);const motion=node('label',null,'guide-toggle');const check=node('input');check.type='checkbox';check.checked=preferences.motion;check.onchange=()=>change('motion',check.checked);motion.append(check,node('span',t('motion')));box.append(motion,node('small',t('motionNote')))}render();host.append(box);return box;}
export function addGuideSettings(host){preferenceControls(host);const label=node('label',null,'guide-toggle');const c=node('input');c.type='checkbox';c.checked=preferences.startup;c.onchange=()=>change('startup',c.checked);label.append(c,node('span',t('startup')));host.append(label,button(t('guide'),()=>openGuide()),button(t('demo'),()=>startTour()));}
function complete(){document.body.classList.remove('guide-open');preferences.startup=false;persist();guide?.close();guide?.remove();guide=null;}
export function openGuide(){endTour();if(guide?.open)return;page=0;guide=node('dialog',null,'user-guide');guide.setAttribute('aria-label',t('guide'));guide.addEventListener('cancel',e=>{e.preventDefault();complete()});document.body.append(guide);renderGuide();document.body.classList.add('guide-open');guide.showModal();}
const local=(zh,hant,en)=>({zh,'zh-Hant':hant,en}[preferences.lang]||en);
function guideImage(src,caption){const f=node('figure'),im=node('img');im.src=src;im.alt=caption;f.append(im,node('figcaption',caption));return f;}
function renderGuide(){
 guide.replaceChildren();const top=node('header');top.append(node('span',t('guide')),node('span',`${page+1} / 5`));const content=node('section',null,'guide-page');
 const titles=[t('welcome'),local('打开作品，浏览照片','開啟作品，瀏覽照片','Open a work and browse photos'),local('阅读完整项目','閱讀完整專案','Read the full project'),local('个人介绍、展览与论文','個人介紹、展覽與論文','Profile, exhibitions & papers'),t('demo')];content.append(node('h1',titles[page]));
 if(page===0)preferenceControls(content);
 if(page===1){const examples=node('div',null,'guide-examples');examples.append(guideImage('assets/guide/desktop.webp',local('① 点击桌面作品，打开照片窗口','① 點擊桌面作品，開啟照片視窗','① Select a desktop work to open its photos')),guideImage('assets/guide/project.webp',local('② 点击右上角蓝色按钮，进入完整项目','② 點擊右上角藍色按鈕，進入完整專案','② Select the blue button at the top right to open the full project')));content.append(examples);}
 if(page===2){content.classList.add('guide-full-page');content.append(guideImage('assets/guide/full-project.webp',local('风从东方来 / 齐文化典籍中心 · 完整项目页面','風從東方來 / 齊文化典籍中心 · 完整專案頁面','Wind from the East · Full project page')));const notes=node('div',null,'guide-page-notes');notes.append(node('p',local('① 研究、设计过程、个人贡献、成果与反思，都在完整项目内阅读。','① 研究、設計過程、個人貢獻、成果與反思，都在完整專案內閱讀。','① Read the research, design process, individual contribution, outcomes and reflection within the full project.')),node('p',local('② 顶部章节导航可直接跳转；绿色按钮进入全屏，移到顶部可找回控制栏。','② 頂部章節導覽可直接跳轉；綠色按鈕進入全螢幕，移到頂部可找回控制列。','② Use the chapter navigation to jump between sections. Green enters fullscreen; move to the top to reveal controls.')));content.append(notes);}
 if(page===3){content.classList.add('guide-research-page');content.append(guideImage('assets/guide/navigation.webp',local('顶部导航：个人介绍 · 项目目录 · 展览与论文','頂部導覽：個人介紹 · 專案目錄 · 展覽與論文','Top navigation: About Me · Project Content · Exhibition & Papers')));const grid=node('div',null,'guide-research-grid');grid.append(guideImage('assets/guide/research.webp',local('① 在 Exhibition & Papers 中点击论文标题或「阅读全文」。','① 在 Exhibition & Papers 中點擊論文標題或「閱讀全文」。','① In Exhibition & Papers, select a paper title or Read Paper.')));const paper=papers[0];const preview=guideImage(paper.preview,local('② 在桌面阅读窗口内查看 PDF，可放大窗口、翻页和下载。点击此预览也可阅读全文。','② 在桌面閱讀視窗內查看 PDF，可放大視窗、翻頁和下載。點擊此預覽也可閱讀全文。','② Read the PDF in a desktop window. Maximize the window, browse pages or download it. You can also select this preview to read it.'));const link=node('a',null,'guide-paper-preview');link.href=paper.pdf;link.onclick=e=>{e.preventDefault();complete();openPaper(paper)};link.setAttribute('aria-label',local('阅读 Path of Light 论文全文（桌面窗口）','閱讀 Path of Light 論文全文（桌面視窗）','Read Path of Light in a desktop window'));link.append(preview.querySelector('img'));preview.prepend(link);grid.append(preview);content.append(grid);}
 if(page===4)content.append(node('div','↗','guide-symbol'),node('p',t('demoNote')),button(t('begin'),()=>{complete();startTour()}));
 const footer=node('footer');if(page>0)footer.append(button(t('back'),()=>{page--;renderGuide()}));footer.append(button(page===4?t('skip'):t('next'),()=>{if(page===4)complete();else{page++;renderGuide()}}));guide.append(top,content,footer);
}
async function showStep(){document.querySelector('.tour-target')?.classList.remove('tour-target');if(step===2)api.project();if(step===3)await api.details();if(!tour)return;const selectors=['.menubar','.desktop-icon','.window:not([hidden]) .full-project-button','.case-window .maximize'];highlight=document.querySelector(selectors[step])||document.querySelector('.window:not([hidden]) .maximize');highlight?.classList.add('tour-target');highlight?.scrollIntoView({block:'nearest'});tour.replaceChildren(node('small',`${step+1} / 4`),node('h2',t(['guide','projects','full','demo'][step])),node('p',t(['navTip','workTip','fullTip','greenTip'][step])));const footer=node('footer');footer.append(button(t('exit'),endTour),button(step===3?t('finish'):t('next'),()=>{if(step===3)endTour();else{step++;showStep()}}));tour.append(footer);tour.querySelector('button')?.focus();}
function endTour(){highlight?.classList.remove('tour-target');tour?.remove();tour=null;document.body.classList.remove('tour-active')}
function startTour(){document.body.classList.remove('guide-open');guide?.close();guide?.remove();guide=null;endTour();step=0;tour=node('aside',null,'guide-tour');tour.setAttribute('role','dialog');tour.setAttribute('aria-label',t('demo'));document.body.append(tour);document.body.classList.add('tour-active');showStep()}
export function initGuide(callbacks){api=callbacks;const entry=button('? '+t('guide'),openGuide);entry.className='guide-entry';document.querySelector('.menu-left').append(entry);apply();let translationFrame=0;new MutationObserver(records=>{if(!records.some(r=>[...r.addedNodes].some(n=>n.nodeType===1)))return;if(!translationFrame)translationFrame=requestAnimationFrame(()=>{translationFrame=0;translate()});}).observe(document.querySelector('#windows'),{childList:true,subtree:true});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&tour)endTour()});if(preferences.startup)setTimeout(openGuide,350);}
